# Provenance for command 13, which manifest_s8.py omitted.
# Does not rewrite the manifest. Do not edit this file after it has run.
import hashlib
import json
from pathlib import Path

names = ['13.cmd.txt', '13.out', '13.err', '13.exit']
rows = []
for name in names:
    path = Path('work/out/cmd') / name
    data = path.read_bytes()
    rows.append({
        'path': 'work/out/cmd/' + name,
        'sha256': hashlib.sha256(data).hexdigest(),
        'bytes': len(data),
    })
exit_rec = json.loads(Path('work/out/cmd/13.exit').read_text(encoding='utf-8'))
doc = {
    'what': 'Command 13 ran manifest_s8.py. That manifest omitted 13.out, 13.err, and 13.exit, and it omitted command 13 from commands. The sentence that every file was included was inaccurate.',
    'files': rows,
    'command': {
        'n': '13',
        'requested': 'python -I work/scripts/manifest_s8.py',
        'status': exit_rec.get('status'),
        'start': exit_rec.get('start'),
        'end': exit_rec.get('end'),
        'scripts': exit_rec.get('scripts'),
        'wrapper_sha256': exit_rec.get('wrapper_sha256'),
    },
    'manifest_limit': 'The manifest refreshed after this supplement lists these four files. It does not hash itself. The wrapper writes the manifest command\'s .out, .err, and .exit after that script returns, so those three are not inside the manifest.',
}
path = Path('work/out/cmd13-supplement-r1.json')
path.write_text(json.dumps(doc, indent=2) + '\n', encoding='utf-8')
print(path)
print(json.dumps(rows, indent=2))
